147	interface MatrixDimensionOption extends MatrixCellStyleOption, MatrixDimensionLevelOption {
148	    type?: 'category'; // For internal usage; force be 'category'.
149	    show?: boolean;
150	    data?: MatrixDimensionCellLooseOption[];
151	    // A simple way to provide column/row count if no need to compose a `data`.
152	    // Note: `length` is ignored if `data` is specified.
153	    length?: number;
154	    // `levels[0]`: the topmost (for x dimension) or leftmost (for y dimension) level.
155	    // If not specified, use null/undefined, such as `levels: [null, null, {levelSize: 10}]`
156	    levels?: (MatrixDimensionLevelOption | NullUndefined)[];
157	    dividerLineStyle?: LineStyleOption;
158	}
159	
160	export interface MatrixDimensionCellOption extends MatrixBaseCellOption {
161	    // Use it to define a coord in matrix.
162	    // Do not use type `OrdinalRawValue` here. Number input is forbiden due to the possible confusion.
163	    // e.g., if `matrix.x.data: [1, 2, 3]` is allowed, then querying `coord: [1, null]` will actually get
164	    // the second column, since number represents the index (i.e. `MatrixXYLocator` or `OrdinalNumber`).
165	    value?: string;
166	    // column width (for x dimension) or row height (for y dimension).
167	    // If not specified (null/undefined), auto calculate it.
168	    // Only available on leaves, to avoid unnecessary complex.
169	    // If it is a percentage, such as '30%', based on the matrix width/height, rather than the canvas size.
170	    size?: PositionSizeOption;
171	    children?: MatrixDimensionCellOption[];
172	}
173	export type MatrixDimensionCellLooseOption = MatrixDimensionCellOption | MatrixDimensionCellOption['value'];
174	
175	export interface MatrixDimensionLevelOption {
176	    // `matrix.levelSize` specifies the default size of every tree levels.
177	    // `matrix.levels[i].levelSize` specifies the size of a certain level.
178	    // For x dimension, that is height; for y dimension, that is width.
179	    // If not specified (null/undefined), auto calculate it.
180	    // If it is a percentage, such as '30%', based on the matrix width/height, rather than the canvas size.
181	    levelSize?: PositionSizeOption;
182	    // Other level specific options may added if needed, such as border-bottom/right style.
183	}
184	
185	export interface MatrixDimensionModel extends Model<MatrixDimensionOption> {
186	}
