188	/**
189	 * Two levels of cascade inheritance:
190	 *  - priority-high: style options defined in `matrix.x/y/coner/body.data[i]` (in cell)
191	 *  - priority-low: style options defined in `matrix.x/y/coner/body`
192	 */
193	export interface MatrixCellStyleOption {
194	    // [NOTE - padding]:
195	    //  - Consider the option for the space between cell boundary to text, percentage value for
196	    //    `label.width/height` is not supported, because it is not ideal - the padding would vary
197	    //    with the cell size, making the layout inconsistent.
198	    //  - The inner text padding uses `lable.style.padding`.
199	    //    The text truncation rect is obtained by cell rect minus by padding.
200	    //  - The inner series / other coord sys padding is not supported, to avoid necessary complexity.
201	    //    Consider some series, such as heatmap, prefer no padding.
202	    label?: LabelOption;
203	    itemStyle?: ItemStyleOption;
204	    cursor?: string;
205	    // By default, auto decide whether to be silent, considering tooltip.
206	    silent?: boolean | NullUndefined;
207	    // Used when style conflict - especially for thick border style.
208	    z2?: number;
209	}
