218	const defaultLabelOption: LabelOption = {
219	    show: true,
220	    color: tokens.color.secondary,
221	    // overflow: 'truncate',
222	    overflow: 'break',
223	    lineOverflow: 'truncate',
224	    padding: [2, 3, 2, 3],
225	    // Prefer to use `padding`, rather than distance.
226	    distance: 0,
