235	const defaultDimOption: MatrixDimensionOption = {
236	    show: true,
237	    label: defaultLabelOption,
238	    itemStyle: makeDefaultCellItemStyleOption(false),
239	    silent: undefined,
240	    dividerLineStyle: {
241	        width: 1,
242	        color: tokens.color.border,
243	    },
244	};
245	const defaultBodyOption: MatrixBodyOption = {
246	    label: defaultLabelOption,
247	    itemStyle: makeDefaultCellItemStyleOption(false),
248	    silent: undefined,
249	};
250	const defaultCornerOption: MatrixCornerOption = {
251	    label: defaultLabelOption,
252	    itemStyle: makeDefaultCellItemStyleOption(true),
253	    silent: undefined,
254	};
255	const defaultMatrixOption: MatrixOption = {
256	    // As a most basic coord sys, `z` should be lower than
257	    // other series and coord sys, such as, grid.
258	    z: -50,
259	    left: '10%',
260	    top: '10%',
261	    right: '10%',
262	    bottom: '10%',
263	    x: defaultDimOption,
264	    y: defaultDimOption,
265	    body: defaultBodyOption,
266	    corner: defaultCornerOption,
267	    backgroundStyle: {
