275	class MatrixModel extends ComponentModel<MatrixOption> implements CoordinateSystemHostModel {
276	    static type = 'matrix';
277	    type = MatrixModel.type;
278	
279	    coordinateSystem: Matrix;
280	
281	    static layoutMode = 'box' as const;
282	
283	    private _dimModels: {
284	        x: MatrixDimensionModel;
285	        y: MatrixDimensionModel;
286	    };
287	
288	    private _body: MatrixBodyCorner<'body'>;
289	    private _corner: MatrixBodyCorner<'corner'>;
290	
291	    static defaultOption: MatrixOption = defaultMatrixOption;
292	
293	    optionUpdated(): void {
294	        // Simply re-create all to follow model changes.
295	
296	        const dimModels = this._dimModels = {
297	            // Do not use matrixModel as the parent model, for preventing from cascade-fetching options to it.
298	            x: new MatrixDimensionModel(this.get('x', true) || {}),
299	            y: new MatrixDimensionModel(this.get('y', true) || {}),
300	        };
301	
302	        dimModels.x.option.type = dimModels.y.option.type = 'category';
303	        const xDim = dimModels.x.dim = new MatrixDim('x', dimModels.x);
304	        const yDim = dimModels.y.dim = new MatrixDim('y', dimModels.y);
305	
306	        const dims = {x: xDim, y: yDim};
307	        this._body = new MatrixBodyCorner(
308	            'body', new Model(this.getShallow('body')), dims
309	        );
310	        this._corner = new MatrixBodyCorner(
311	            'corner', new Model(this.getShallow('corner')), dims
312	        );
313	    }
314	
315	    getDimensionModel(dim: 'x' | 'y'): MatrixDimensionModel {
316	        return this._dimModels[dim];
317	    }
318	
319	    getBody(): MatrixBodyCorner<'body'> {
320	        return this._body;
321	    }
322	
323	    getCorner(): MatrixBodyCorner<'corner'> {
324	        return this._corner;
325	    }
326	
327	}
328	
329	export class MatrixDimensionModel extends Model<MatrixDimensionOption> {
330	    dim: MatrixDim;
331	    getOrdinalMeta(): OrdinalMeta {
332	        return this.dim.getOrdinalMeta();
333	    }
334	}
335	
336	export default MatrixModel;

