485	const CtxPointToDataAreaType = {inBody: 1, inCorner: 2, outside: 3};
486	type CtxPointToDataAreaType = (typeof CtxPointToDataAreaType)[keyof typeof CtxPointToDataAreaType];
487	type CtxPointToData = {
488	    x: CtxPointToDataAreaType | NullUndefined;
489	    y: CtxPointToDataAreaType | NullUndefined;
490	    point: number[]; // If clamp required, this point is clamped after prepared.
491	};
