199	        dimForCoordX: MatrixDim, // Can be `matrix.y` (transposed) for corners.
200	        dimForCoordY: MatrixDim, // Can be `matrix.x` (trnasposed) for corners.
201	    ): void {
202	        // Prevent inheriting from ancestor.
203	        const parentCellModel = new Model(matrixModel.getShallow(bodyCornerOptionRoot, true));
