212	        for (dimForCoordY.resetLayoutIterator(ity, 1); ity.next();) {
213	            for (dimForCoordX.resetLayoutIterator(itx, 0); itx.next();) {
214	                const xLayout = itx.item;
215	                const yLayout = ity.item;
216	
217	                vectorUtil.set(xyLocator, xLayout.id.x, yLayout.id.y);
218	                const bodyCornerCell = bodyOrCorner.getCell(xyLocator);
