270	    _tmpCellItemStyleModel.option = cellOption ? cellOption.itemStyle : null;
271	    _tmpCellItemStyleModel.parentModel = parentItemStyleModel;
272	    _tmpCellModel.option = cellOption;
273	    _tmpCellModel.parentModel = parentCellModel;
274	
275	    // Use different z2 becuase special border may be defined in itemStyle.
276	    const z2 = retrieve2(
277	        _tmpCellModel.getShallow('z2'),
278	        (cellOption && cellOption.itemStyle) ? zrCellDefault.special : zrCellDefault.normal
279	    );
280	    const tooltipOptionShow = tooltipOption && tooltipOption.show;
281	
282	    const cellRect = createMatrixRect(shape, _tmpCellItemStyleModel.getItemStyle(), z2);
283	    group.add(cellRect);
284	
285	    const cursorOption = _tmpCellModel.get('cursor');
286	    if (cursorOption != null) {
287	        cellRect.attr('cursor', cursorOption);
288	    }
289	    let cellText: Text | NullUndefined;
290	
291	    if (textValue != null) {
292	        const text = textValue + '';
293	        _tmpCellLabelModel.option = cellOption ? cellOption.label : null;
294	        _tmpCellLabelModel.parentModel = parentLabelModel;
295	        // This is to accept `option.textStyle` as the default.
296	        _tmpCellLabelModel.ecModel = ecModel;
