298	        setLabelStyle(
299	            cellRect,
300	            // Currently do not support other states (`emphasis`, `select`, `blur`)
301	            {normal: _tmpCellLabelModel},
302	            {
303	                defaultText: text,
304	                autoOverflowArea: true,
305	                // By default based on boundingRect. But boundingRect contains borderWidth,
306	                // and borderWidth is half outside the cell. Thus specific `layoutRect` explicitly.
307	                layoutRect: clone(cellRect.shape)
308	            },
309	        );
310	        cellText = cellRect.getTextContent();
311	        if (cellText) {
312	            cellText.z2 = z2 + 1;
313	
314	            const style = cellText.style;
315	            if (style && (style.overflow && style.overflow !== 'none' && style.lineOverflow)) {
