326	                cellText.setClipPath(new Rect({shape: clipShape}));
327	            }
328	        }
329	
330	        setTooltipConfig({ // At least for text overflow.
331	            el: cellRect,
332	            componentModel: matrixModel,
333	            itemName: text,
334	            itemTooltipOption: tooltipOption,
335	            formatterParamsExtra: {
336	                xyLocator: xyLocator.slice()
337	            }
338	        });
339	    }
340	
341	    // Set silent
342	    if (cellText) {
343	        let labelSilent = _tmpCellLabelModel.get('silent');
344	        // auto, tooltip of text cells need silient: false, but non-text cells
345	        // do not need a special cursor in most cases.
346	        if (labelSilent == null) {
347	            labelSilent = !tooltipOptionShow;
348	        }
349	        cellText.silent = labelSilent;
350	        cellText.ignoreHostSilent = true;
351	    }
352	    let rectSilent = _tmpCellModel.get('silent');
353	    if (rectSilent == null) {
354	        rectSilent = (
355	            // If no background color in cell, set `rect.silent: false` will cause that only
356	            // the border response to mouse hovering, which is probably weird.
357	            !cellRect.style || cellRect.style.fill === 'none' || !cellRect.style.fill
358	        );
359	    }
360	    cellRect.silent = rectSilent;
361	
362	    clearTmpModel(_tmpCellModel);
363	    clearTmpModel(_tmpCellItemStyleModel);
364	    clearTmpModel(_tmpCellLabelModel);
365	}
366	const _tmpCellModel = new Model<MatrixCellStyleOption>();
367	const _tmpCellItemStyleModel = new Model<MatrixCellStyleOption['itemStyle']>();
368	const _tmpCellLabelModel = new Model<MatrixCellStyleOption['label']>();
369	const _tmpInnerTextTrans: number[] = [];
