371	// FIXME: move all of the subpixel process to Matrix.ts resize, otherwise the result of
372	// `dataToLayout` is not consistent with this rendering, and the caller (like heatmap) can
373	// not precisely align with the matrix border.
374	function createMatrixRect(
375	    shape: RectShape, style: ItemStyleProps, z2: number
376	): Rect {
377	    // Currently `subPixelOptimizeRect` can not be used here because it will break rect alignment.
378	    // Optimize line and rect with the same direction.
379	    const lineWidth = style.lineWidth;
380	    if (lineWidth) {
381	        const x2Original = shape.x + shape.width;
382	        const y2Original = shape.y + shape.height;
383	        shape.x = subPixelOptimize(shape.x, lineWidth, true);
384	        shape.y = subPixelOptimize(shape.y, lineWidth, true);
385	        shape.width = subPixelOptimize(x2Original, lineWidth, true) - shape.x;
386	        shape.height = subPixelOptimize(y2Original, lineWidth, true) - shape.y;
387	    }
388	    return new Rect({
389	        shape,
390	        style: style,
391	        z2,
392	    });
393	}
394	
395	function createMatrixLine(shape: Omit<LineShape, 'percent'>, style: LineStyleProps, z2: number): Line {
396	    const lineWidth = style.lineWidth;
397	    if (lineWidth) {
398	        if (round(shape.x1 * 2) === round(shape.x2 * 2)) {
399	            shape.x1 = shape.x2 = subPixelOptimize(shape.x1, lineWidth, true);
400	        }
401	        if (round(shape.y1 * 2) === round(shape.y2 * 2)) {
402	            shape.y1 = shape.y2 = subPixelOptimize(shape.y1, lineWidth, true);
403	        }
404	    }
405	    return new Line({
406	        shape,
407	        style,
408	        silent: true,
409	        z2,
410	    });
411	}
