import { createChart, removeChart } from '../../test/ut/core/utHelper';

function getMatrixView(chart: ReturnType<typeof createChart>) {
    const matrixModel = (chart.getModel() as any).getComponent('matrix');
    return (chart as any).getViewOfComponentModel(matrixModel);
}

function collectTextRects(view: any): Record<string, any> {
    const rectByText: Record<string, any> = {};
    view.group.traverse(function (el: any) {
        const textEl = el.getTextContent && el.getTextContent();
        const text = textEl && textEl.style && textEl.style.text;
        if (text && !rectByText[text]) {
            rectByText[text] = el;
        }
    });
    return rectByText;
}

describe('matrix-label-api', function () {

    it('matrix labels inherit option.textStyle defaults', function () {
        const chart = createChart();
        chart.setOption({
            textStyle: {
                fontSize: 37
            },
            matrix: {
                x: {data: ['A', 'B']},
                y: {data: ['C', 'D']},
                body: {
                    data: [{coord: ['A', 'C'], value: 'cellText'}]
                }
            }
        });

        const view = getMatrixView(chart);
        const texts: any[] = [];
        view.group.traverse(function (el: any) {
            const textEl = el.getTextContent && el.getTextContent();
            if (textEl) {
                texts.push(textEl);
            }
        });
        // Both dimension labels and body cell labels exist.
        expect(texts.length).toBeGreaterThanOrEqual(5);
        // `fontSize` is not set by matrix defaults, so it must fall back
        // to `option.textStyle`.
        for (const textEl of texts) {
            expect(textEl.style.fontSize).toBe(37);
        }

        removeChart(chart);
    });

    it('coordinate lookup handles missing or out-of-range locators predictably', function () {
        const chart = createChart();
        chart.setOption({
            matrix: {
                x: {data: ['A', 'B']},
                y: {data: ['C', 'D']}
            }
        });

        // Missing locator on one dim: that dim is NaN, the other is resolved.
        const pxMissingX = chart.convertToPixel({matrixIndex: 0}, [null, 'C']);
        expect(pxMissingX[0]).toBeNaN();
        expect(pxMissingX[1]).not.toBeNaN();

        // Out-of-range locator resolves to NaN (no clamp by default).
        const pxOut = chart.convertToPixel({matrixIndex: 0}, [99, 'C']);
        expect(pxOut[0]).toBeNaN();
        expect(pxOut[1]).not.toBeNaN();

        // Invalid locators on both dims: must not crash (cell merge expansion
        // used to throw on NaN locators), and produce a NaN rect.
        const layoutInvalid = chart.convertToLayout({matrixIndex: 0}, ['noX', 'noY']);
        expect(layoutInvalid.rect.x).toBeNaN();
        expect(layoutInvalid.rect.y).toBeNaN();
        expect(layoutInvalid.rect.width).toBeNaN();
        expect(layoutInvalid.rect.height).toBeNaN();

        // A locator list with more than two parts is treated as [first, last].
        const layoutRange = chart.convertToLayout({matrixIndex: 0}, [[0, 1, 1], 0]);
        const layoutRangeRef = chart.convertToLayout({matrixIndex: 0}, [[0, 1], 0]);
        expect(layoutRange.rect.x).toBeCloseTo(layoutRangeRef.rect.x);
        expect(layoutRange.rect.width).toBeCloseTo(layoutRangeRef.rect.width);

        removeChart(chart);
    });

    it('coordClamp refers to the entire column/row only when enabled', function () {
        const chart = createChart();
        chart.setOption({
            matrix: {
                x: {data: ['A', 'B']},
                y: {data: ['C', 'D']},
                body: {
                    data: [
                        {coord: ['B', null], coordClamp: true, value: 'clampCell'},
                        {coord: ['A', null], value: 'noClampCell'}
                    ]
                }
            }
        });

        const rectByText = collectTextRects(getMatrixView(chart));

        // `coordClamp: true` makes `['B', null]` cover the entire column (both rows).
        const clampRect = rectByText['clampCell'];
        expect(clampRect).toBeTruthy();
        const fullColLayout = chart.convertToLayout({matrixIndex: 0}, ['B', [0, 1]]);
        // The rendered rect is sub-pixel optimized, allow a small deviation.
        expect(Math.abs(clampRect.shape.y - fullColLayout.rect.y)).toBeLessThan(1.5);
        expect(Math.abs(clampRect.shape.height - fullColLayout.rect.height)).toBeLessThan(1.5);

        // Without `coordClamp`, the partial-null coord is invalid and no cell is created.
        expect(rectByText['noClampCell']).toBeFalsy();

        removeChart(chart);
    });
});

