import { createChart, removeChart } from '../../test/ut/core/utHelper';

function getMatrixView(chart: ReturnType<typeof createChart>) {
    const matrixModel = (chart.getModel() as any).getComponent('matrix');
    return (chart as any).getViewOfComponentModel(matrixModel);
}

function collectTexts(view: any): string[] {
    const texts: string[] = [];
    view.group.traverse(function (el: any) {
        const textEl = el.getTextContent && el.getTextContent();
        const text = textEl && textEl.style && textEl.style.text;
        if (text) {
            texts.push(text);
        }
    });
    return texts;
}

describe('matrix-label-formatter', function () {

    it('string template formatter applies to matrix labels', function () {
        const chart = createChart();
        chart.setOption({
            matrix: {
                x: {
                    data: ['A', 'B'],
                    label: {formatter: 'Col: {name}'}
                },
                y: {
                    data: ['C', 'D'],
                    label: {formatter: 'Row: {name}'}
                }
            }
        });

        const texts = collectTexts(getMatrixView(chart));
        expect(texts).toContain('Col: A');
        expect(texts).toContain('Col: B');
        expect(texts).toContain('Row: C');
        expect(texts).toContain('Row: D');
        // Raw values must not be rendered.
        expect(texts).not.toContain('A');
        expect(texts).not.toContain('C');

        removeChart(chart);
    });

    it('function formatter applies and receives the matrix label context', function () {
        const chart = createChart();
        const paramsList: any[] = [];
        chart.setOption({
            matrix: {
                x: {data: ['A', 'B']},
                y: {data: ['C', 'D']},
                body: {
                    data: [{coord: ['B', 'D'], value: 'rawValue'}],
                    label: {
                        formatter: function (params: any) {
                            paramsList.push(params);
                            return 'fmt:' + params.name;
                        }
                    }
                }
            }
        });

        const texts = collectTexts(getMatrixView(chart));
        expect(texts).toContain('fmt:rawValue');
        expect(texts).not.toContain('rawValue');

        // The formatter callback receives the documented context.
        expect(paramsList.length).toBeGreaterThan(0);
        const params = paramsList[0];
        expect(params.componentType).toBe('matrix');
        expect(params.name).toBe('rawValue');
        expect(params.value).toBe('rawValue');
        expect(params.xyLocator).toEqual([1, 1]);

        removeChart(chart);
    });

    it('function formatter on dimension labels applies to every cell', function () {
        const chart = createChart();
        chart.setOption({
            matrix: {
                x: {
                    data: [{
                        value: 'Group',
                        children: ['A1', 'A2']
                    }],
                    label: {
                        formatter: function (params: any) {
                            return '[' + params.name + ']';
                        }
                    }
                },
                y: {data: ['C']}
            }
        });

        const texts = collectTexts(getMatrixView(chart));
        expect(texts).toContain('[Group]');
        expect(texts).toContain('[A1]');
        expect(texts).toContain('[A2]');

        removeChart(chart);
    });
});
